{
  "presentationDefinition": {
    "id": "pd-generic-jsonld",
    "name": "Verificación de credencial genérica JSON-LD",
    "purpose": "Verificar identidad y número de documento",
    "input_descriptors": [
      {
        "id": "generic-credential",
        "name": "Credencial genérica",
        "purpose": "Presentar una GenericCredential que incluya nombre y documento",
        "format": {
          "ldp_vc": {
            "proof_type": ["Ed25519Signature2018"]
          }
        },
        "constraints": {
          "fields": [
            {
              "path": ["$.type"],
              "filter": {
                "type": "array",
                "contains": { "const": "GenericCredential" }
              }
            },
            { "path": ["$.credentialSubject.name"] },
            { "path": ["$.credentialSubject.documentNumber"] }
          ]
        }
      }
    ]
  },
  "expiresInSeconds": 1800
}

{
  "presentationDefinition": {
    "id": "pd-generic-bbs",
    "name": "Verificación BBS+ con selective disclosure",
    "purpose": "Revelar solo el nombre; documentNumber queda oculto",
    "input_descriptors": [
      {
        "id": "generic-credential-bbs",
        "name": "GenericCredential BBS+",
        "purpose": "Presentar VC firmada con BbsBlsSignature2020 revelando solo name",
        "format": {
          "ldp_vc": {
            "proof_type": ["BbsBlsSignature2020", "BbsBlsSignatureProof2020"]
          }
        },
        "constraints": {
          "fields": [
            {
              "path": ["$.type"],
              "filter": {
                "type": "array",
                "contains": { "const": "GenericCredential" }
              }
            },
            { "path": ["$.credentialSubject.name"] }
          ]
        }
      }
    ]
  },
  "expiresInSeconds": 1800
}
